-- Append-only evidence of affirmative click-through acceptance. The timestamp
-- is generated by Postgres rather than supplied by the client. Users may read
-- and insert their own records, but cannot update or delete them.

create table if not exists public.legal_acceptances (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  legal_terms_version text not null check (char_length(legal_terms_version) between 1 and 50),
  privacy_policy_version text not null check (char_length(privacy_policy_version) between 1 and 50),
  acceptance_source text not null default 'ios_clickwrap'
    check (acceptance_source in ('ios_clickwrap')),
  app_version text,
  app_build text,
  accepted_at timestamptz not null default now()
);

create index if not exists legal_acceptances_user_time_idx
  on public.legal_acceptances (user_id, accepted_at desc);

alter table public.legal_acceptances enable row level security;

create policy "users insert their own legal acceptance"
on public.legal_acceptances for insert to authenticated
with check (user_id = auth.uid());

create policy "users view their own legal acceptance"
on public.legal_acceptances for select to authenticated
using (user_id = auth.uid());

revoke all on public.legal_acceptances from anon;
revoke update, delete on public.legal_acceptances from authenticated;
grant select, insert on public.legal_acceptances to authenticated;

comment on table public.legal_acceptances is
  'Append-only record of affirmative Terms acceptance and Privacy Policy acknowledgement.';
